import { AbsoluteFill, OffthreadVideo, staticFile } from "remotion";

/**
 * Full-screen presenter scene: the HeyGen clip generated by
 * scripts/presenter.mjs for this scene id. The clip's audio IS the scene's
 * narration (it was lip-synced from the narration MP3), so no separate
 * narration track is mounted for presenter scenes.
 */
export const PresenterScene = ({ sceneId }: { sceneId: string }) => (
  <AbsoluteFill style={{ background: "#000" }}>
    <OffthreadVideo src={staticFile(`presenter/${sceneId}.mp4`)} />
  </AbsoluteFill>
);
